Question: Write a function void findMinMax(int arr[], int &min, int &max, int size) that finds the minimum and maximum values in an array and stores them in the reference variables min and max.

Code:
#include <iostream>
#include <climits>
using namespace std;

void findMinMax(int arr[], int &min, int &max, int size) {
    if (size <= 0 || arr == nullptr) {
        // Handle invalid input gracefully
        // Depending on requirements, could throw exception or set error codes.
        // For this signature, we might just return without modifying or set to safe defaults.
        return; 
    }

    min = arr[0];
    max = arr[0];

    for (int i = 1; i < size; i++) {
        if (arr[i] < min) {
            min = arr[i];
        }
        if (arr[i] > max) {
            max = arr[i];
        }
    }
}

int main() {
    int arr[] = {10, 2, 5, 8, 1, 9};
    int min, max;
    int size = sizeof(arr) / sizeof(arr[0]);

    findMinMax(arr, min, max, size);

    cout << "Min: " << min << endl;
    cout << "Max: " << max << endl;

    return 0;
}

Question: Write a function int searchData(int arr[], int size, int key) that searches for the key in the array using linear search and returns the index. Return -1 if not found.

Code:
#include <iostream>
using namespace std;

int searchData(int arr[], int size, int key) {
    if (arr == nullptr || size <= 0) {
        return -1;
    }

    for (int i = 0; i < size; i++) {
        if (arr[i] == key) {
            return i;
        }
    }
    return -1;
}

int main() {
    int arr[] = {10, 20, 30, 40, 50};
    int size = sizeof(arr) / sizeof(arr[0]);
    int key = 30;

    int index = searchData(arr, size, key);

    if (index != -1) {
        cout << "Element found at index: " << index << endl;
    } else {
        cout << "Element not found" << endl;
    }

    return 0;
}

Question: Write a function int searchData(int arr[], int size, int key) that performs binary search to find the key in the sorted array. Return the index if found, -1 otherwise.

Code:
#include <iostream>
using namespace std;

int searchData(int arr[], int size, int key) {
    if (arr == nullptr || size <= 0) {
        return -1;
    }

    int start = 0;
    int end = size - 1;

    while (start <= end) {
        // Prevent integer overflow for large indices
        int mid = start + (end - start) / 2;

        if (arr[mid] == key) {
            return mid;
        } else if (key < arr[mid]) {
            end = mid - 1;
        } else {
            start = mid + 1;
        }
    }
    return -1;
}

int main() {
    int arr[] = {-1, 0, 1, 2, 10, 34, 40, 44, 51, 99};
    int size = sizeof(arr) / sizeof(arr[0]);

    int key1 = 40;
    int index1 = searchData(arr, size, key1);
    if (index1 != -1) cout << key1 << " found at index " << index1 << endl;
    else cout << key1 << " not found" << endl;

    int key2 = 999;
    int index2 = searchData(arr, size, key2);
    if (index2 != -1) cout << key2 << " found at index " << index2 << endl;
    else cout << key2 << " not found" << endl;

    return 0;
}

Question: Write a function void CheckFrequency(int arr[], int size) that prints the frequency of each element in the array.

