}

Question: Write a function void binomSum(int arr[], int size) that updates each element with the sum of numbers from 1 to that element.

Code:
#include <iostream>
using namespace std;

void binomSum(int arr[], int size) {
    if (arr == nullptr || size <= 0) {
        return;
    }

    for (int i = 0; i < size; i++) {
        int n = arr[i];
        if (n <= 0) {
            arr[i] = 0;
        } else {
            // Use long long to prevent overflow during multiplication
            long long sum = (static_cast<long long>(n) * (n + 1)) / 2;
            arr[i] = static_cast<int>(sum);
        }
    }
}

int main() {
    int arr[] = {6, 4, 1, 3, 0, -5};
    int size = sizeof(arr) / sizeof(arr[0]);

    binomSum(arr, size);

    cout << "Output Array: ";
    for (int i = 0; i < size; i++) {
        cout << arr[i] << " ";
    }
    cout << endl;

    return 0;
}

Question: Write a function int findLongestPalindrome(const char arr[]) that returns the length of the longest palindromic substring.

Code:
#include <iostream>
#include <cstring>
#include <algorithm>
using namespace std;

int findLongestPalindrome(const char arr[]) {
    if (arr == nullptr) return 0;

    int n = strlen(arr);
    if (n == 0) return 0;

    int maxLength = 1;

    // Expand Around Center approach O(N^2)
    for (int i = 0; i < n; i++) {
        // Odd length palindromes (center is i)
        int l = i, r = i;
        while (l >= 0 && r < n && arr[l] == arr[r]) {
            if (r - l + 1 > maxLength) {
                maxLength = r - l + 1;
            }
            l--;
            r++;
        }

        // Even length palindromes (center is between i and i+1)
        l = i; r = i + 1;
        while (l >= 0 && r < n && arr[l] == arr[r]) {
            if (r - l + 1 > maxLength) {
                maxLength = r - l + 1;
            }
            l--;
            r++;
        }
    }
    return maxLength;
}

int main() {
    const char arr1[] = "babad";
    cout << "Length: " << findLongestPalindrome(arr1) << endl;

    const char arr2[] = "cbbd";
    cout << "Length: " << findLongestPalindrome(arr2) << endl;

    const char* arr3 = NULL;
    cout << "Length: " << findLongestPalindrome(arr3) << endl;

    return 0;
}

Question: Write a function void findMissingElements(const int arr1[], int size1, const int arr2[], int size2, int result[], int& resultSize) that finds elements in arr1 but not in arr2 (both sorted).

Code:
#include <iostream>
using namespace std;

void findMissingElements(const int arr1[], int size1, const int arr2[], int size2, int result[], int& resultSize) {
    if (arr1 == nullptr && size1 > 0) return; // Error or assume empty?
    // If result is null, we can't write. 
    if (result == nullptr) {
        resultSize = 0;
        return;
    }

    // Two pointer approach O(N + M)
    int i = 0, j = 0, k = 0;

    // Handle potential nullptrs for inputs if sizes are 0
    // If arr2 is null/empty, all arr1 goes to result
    if (arr2 == nullptr || size2 <= 0) {
        if (arr1 != nullptr) {
            for (int x = 0; x < size1; x++) result[k++] = arr1[x];
        }
        resultSize = k;
        return;
    }
    if (arr1 == nullptr || size1 <= 0) {
        resultSize = 0;
        return;
    }

    while (i < size1 && j < size2) {
        if (arr1[i] < arr2[j]) {
            result[k++] = arr1[i];
            i++;
        } else if (arr1[i] > arr2[j]) {
            j++;
        } else {
            // Equal: skip both
            i++;
            j++;
        }
    }

    // Add remaining elements from arr1
    while (i < size1) {
        result[k++] = arr1[i];
        i++;
    }

    resultSize = k;
}

int main() {
    int arr1[] = {1, 2, 3, 4, 5, 10, 12};
    int arr2[] = {2, 4, 10};
    int result[20];
    int resultSize = 0;

    findMissingElements(arr1, 7, arr2, 3, result, resultSize);

    cout << "Missing Elements: ";
    for (int i = 0; i < resultSize; i++) {
        cout << result[i] << " ";
    }
    cout << endl;

    return 0;
}

Question: Write a function int findConsecutiveZeros(const char arr[]) that returns the maximum number of consecutive '0' characters.

Code:
#include <iostream>
#include <cstring>
#include <algorithm>
using namespace std;

int findConsecutiveZeros(const char arr[]) {
    if (arr == nullptr) {
        return 0;
    }

    int maxZeros = 0;
    int currentZeros = 0;

    for (int i = 0; arr[i] != '\0'; i++) {
        if (arr[i] == '0') {
            currentZeros++;
        } else {
            if (currentZeros > maxZeros) {
                maxZeros = currentZeros;
            }
            currentZeros = 0;
        }
    }
    // Check after loop finishes in case array ends with zeros
    if (currentZeros > maxZeros) {
        maxZeros = currentZeros;
    }

    return maxZeros;
}

int main() {
    const char arr1[] = "10010001";
    cout << "Max Consecutive Zeros: " << findConsecutiveZeros(arr1) << endl;

    const char arr2[] = "0000";
    cout << "Max Consecutive Zeros: " << findConsecutiveZeros(arr2) << endl;

    const char* arr3 = NULL;
    cout << "Max Consecutive Zeros: " << findConsecutiveZeros(arr3) << endl;

    return 0;
}

Question: Write a function void findDuplicateCharacters(const char arr[], char duplicates[], int& duplicatesSize) that finds duplicate characters in the string.

Code:
#include <iostream>
#include <cstring>
#include <algorithm>
using namespace std;

void findDuplicateCharacters(const char arr[], char duplicates[], int& duplicatesSize) {
    if (arr == nullptr || duplicates == nullptr) {
        duplicatesSize = 0;
        return;
    }

    int counts[256] = {0}; // Assuming ASCII
    int k = 0;

    for (int i = 0; arr[i] != '\0'; i++) {
        unsigned char c = (unsigned char)arr[i];
        counts[c]++;
    }

    // Collect duplicates
    // Requirement says "returns... duplicate characters". Order usually not specified strictly,
    // but often order of first appearance or alphabetical.
    // Iterating 0..255 gives alphabetical order.
    // Iterating array again gives order of appearance.
    // Let's stick to alphabetical/ASCII order for stability.

    for (int i = 0; i < 256; i++) {
        if (counts[i] > 1) {
            duplicates[k++] = (char)i;
        }
    }
    duplicatesSize = k;
}

int main() {
    const char arr[] = "programming";
    char duplicates[20];
    int duplicatesSize = 0;

    findDuplicateCharacters(arr, duplicates, duplicatesSize);

    cout << "Duplicates: ";
    for (int i = 0; i < duplicatesSize; i++) {
        cout << duplicates[i] << " ";
    }
    cout << endl;

    return 0;
}

Question: Write a function void findCharacterFrequency(const char arr[], int frequency[]) that counts occurrences of each character.

Code:
#include <iostream>
#include <cstring>
using namespace std;

void findCharacterFrequency(const char arr[], int frequency[]) {
    if (arr == nullptr || frequency == nullptr) {
        return;
    }

    // Initialize frequency array to 0 is often expected if function claims to find frequency
    // But since it's passed in, we should clarify. Assuming we should zero it out first or just add?
    // Usually "find frequency" implies starting from 0.
    // However, if we don't know the size of frequency array (assumed 256), clearing it is unsafe if caller passed smaller.
    // The safest "correct" version compliant with C++ arrays simply iterates. 
    // We assume caller provides zeroed array or valid state.

    for (int i = 0; arr[i] != '\0'; i++) {
        unsigned char c = (unsigned char)arr[i]; // Cast to unsigned to handle extended ASCII safely
        frequency[c]++;
    }
}

int main() {
    const char arr[] = "hello";
    int frequency[256] = {0}; // Initialize to 0

    findCharacterFrequency(arr, frequency);

    for (int i = 0; i < 256; i++) {
        if (frequency[i] > 0) {
            cout << (char)i << ": " << frequency[i] << endl;
        }
    }

    // Robustness test
    findCharacterFrequency(NULL, frequency); // Should safe return

    return 0;
}

Question: Write a function void reverseWords(char arr[]) that reverses the order of words in the string.

Code:
#include <iostream>
#include <cstring>
#include <algorithm>
using namespace std;

void reverseWords(char arr[]) {
    if (arr == nullptr) return;

    int n = strlen(arr);
    if (n == 0) return;

    // Step 1: Reverse the whole string
    // "Hello World" -> "dlroW olleH"
    reverse(arr, arr + n);

    // Step 2: Reverse each word individually
    // "dlroW" -> "World", "olleH" -> "Hello"
    int start = 0;
    for (int end = 0; end < n; end++) {
        if (arr[end] == ' ') {
            reverse(arr + start, arr + end);
            start = end + 1;
        }
    }
    // Reverse the last word
    reverse(arr + start, arr + n);
}

int main() {
    char arr1[] = "Hello World";
    reverseWords(arr1);
    cout << "Reversed: " << arr1 << endl;

    char arr2[] = "One";
    reverseWords(arr2);
    cout << "Reversed: " << arr2 << endl;

    char arr3[] = "  Space  Test  ";
    // Note: Standard "reverse words" usually preserves spaces or collapses them.
    // This in-place reversal preserves all spaces.
    // "  Space  Test  " -> "  tseT  ecapS  " (reversed chars)
    // Then reverse words: "  Test  Space  "
    reverseWords(arr3);
    cout << "Reversed: '" << arr3 << "'" << endl;

    return 0;
}

Question: Write a function void replaceSubstring(char arr[], const char target[], const char replacement[]) that replaces all occurrences of target with replacement.

Code:
#include <iostream>
#include <cstring>
#include <cstdlib>
using namespace std;

void replaceSubstring(char arr[], const char target[], const char replacement[]) {
    if (arr == nullptr || target == nullptr || replacement == nullptr) return;

    int targetLen = strlen(target);
    int repLen = strlen(replacement);

    if (targetLen == 0) return; // Prevent infinite loop if target is empty

    // Calculate new length to ensure buffer size
    int count = 0;
    char *p = arr;
    while ((p = strstr(p, target)) != nullptr) {
        count++;
        p += targetLen;
    }

    int newLen = strlen(arr) + count * (repLen - targetLen);

    // We assume 'arr' is large enough to hold the result as per standard C-style interface contract
    // (or we would need a max size param). For safety in this specific task logic, we use a temp buffer.

    char* buffer = (char*)malloc(newLen + 1);
    if (buffer == nullptr) return;

    char* src = arr;
    char* dst = buffer;

    while (*src) {
        if (strncmp(src, target, targetLen) == 0) {
            strcpy(dst, replacement);
            dst += repLen;
            src += targetLen;
        } else {
            *dst++ = *src++;
        }
    }
    *dst = '\0';

    strcpy(arr, buffer);
    free(buffer);
}

int main() {
    char arr[100] = "hello world, hello universe";
    replaceSubstring(arr, "hello", "hi");
    cout << "Result: " << arr << endl;

    char arr2[100] = "aaaa";
    replaceSubstring(arr2, "aa", "b");
    cout << "Result: " << arr2 << endl; // "bb"

    return 0;
}

Question: Write a function int countCharacterOccurrences(const char arr[], char target) that counts occurrences of target in arr.

