    cout << "Original: " << arr << endl;

    encrypt(arr);
    cout << "Encrypted: " << arr << endl;

    decrypt(arr);
    cout << "Decrypted: " << arr << endl;

    // Test with NULL
    encrypt(NULL);
    decrypt(NULL);

    return 0;
}

