    // H(1,2), I(1,3), N(2,3) -> HIN
    // H(1,2), G(1,1), F(1,0) -> HGF
    // H(1,2), M(2,2), R(3,2) -> HMR
    // Let's try 'GLQ' (1,1)->(2,1)->(3,1).
    if (searchWord(grid, "GLQ")) {
        // Found
    } else {
        cout << "GLQ Not found" << endl;
    }

    searchWord(grid, "AFK"); // 0,0 -> 1,0 -> 2,0

