Question: Write a function void rotateMatrix(int matrix[][N], int n) that rotates a square matrix 90 degrees clockwise in-place.

Code:
#include <iostream>
#include <iomanip>
#include <algorithm>
using namespace std;

const int N = 3;

void rotateMatrix(int matrix[][N], int n) {
    if (n <= 0 || n > N) return;

    // Step 1: Transpose the matrix
    for (int i = 0; i < n; i++) {
        for (int j = i; j < n; j++) {
            swap(matrix[i][j], matrix[j][i]);
        }
    }

    // Step 2: Reverse each row
    for (int i = 0; i < n; i++) {
        // Reverse row i
        for (int j = 0; j < n / 2; j++) {
            swap(matrix[i][j], matrix[i][n - 1 - j]);
        }
    }
}

int main() {
    int matrix[N][N] = {
        {1, 2, 3},
        {4, 5, 6},
        {7, 8, 9}
    };

    cout << "Original:" << endl;
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) cout << matrix[i][j] << " ";
        cout << endl;
    }

    rotateMatrix(matrix, N);

    cout << "Rotated:" << endl;
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) cout << matrix[i][j] << " ";
        cout << endl;
    }

    // Robustness test
    rotateMatrix(matrix, 10);

    return 0;
}

