void mergeArrays(const int arr1[], int n1, const int arr2[], int n2, int result[]) {
    if ((arr1 == nullptr && n1 > 0) || (arr2 == nullptr && n2 > 0) || result == nullptr) {
        return; 
    }

    int i = 0, j = 0, k = 0;

    while (i < n1 && j < n2) {
        if (arr1[i] <= arr2[j]) {
            result[k++] = arr1[i++];
        } else {
            result[k++] = arr2[j++];
        }
    }

    while (i < n1) {
        result[k++] = arr1[i++];
    }

    while (j < n2) {
        result[k++] = arr2[j++];
    }
}

