const int MAX = 10;

void multiplyMatrices(int A[][MAX], int B[][MAX], int C[][MAX], int m, int n, int p) {
    if (m <= 0 || n <= 0 || p <= 0 || m > MAX || n > MAX || p > MAX) {
        return; // Or handle error
