    int n = sizeof(arr) / sizeof(arr[0]);

    moveZeroes(arr, n);

    cout << "Result: ";
    for (int i = 0; i < n; i++) {
        cout << arr[i] << " ";
    }
    cout << endl;

    moveZeroes(NULL, 0); // Safe
