int maxSubArray(int arr[], int n) {
    if (arr == nullptr || n <= 0) return 0; // Or specific error code/behavior

    int maxSoFar = arr[0]; // Initialize with first element to handle all-negative case correctly
    int maxEndingHere = arr[0];

    for (int i = 1; i < n; i++) {
