    if (str == nullptr) return false; // Let's say invalid input is false

    int balance = 0;
    for (int i = 0; str[i] != '\0'; i++) {
        if (str[i] == '(') {
            balance++;
        } else if (str[i] == ')') {
            balance--;
        }

        if (balance < 0) {
            return false;
        }
    }

    return balance == 0;
}

