}

Question: Write a function Node* mergeLists(Node* head1, Node* head2) that merges two sorted linked lists.

Code:
#include <iostream>
using namespace std;

struct Node {
    int data;
    Node* next;
};

// Iterative approach for O(N) time and O(1) space (robust against stack overflow)
Node* mergeLists(Node* head1, Node* head2) {
    if (head1 == nullptr) return head2;
    if (head2 == nullptr) return head1;

    Node dummy; // Stack-allocated dummy node to simplify head logic
    Node* tail = &dummy;

    while (head1 != nullptr && head2 != nullptr) {
        if (head1->data <= head2->data) {
            tail->next = head1;
            head1 = head1->next;
        } else {
            tail->next = head2;
            head2 = head2->next;
        }
        tail = tail->next;
    }

    if (head1 != nullptr) {
        tail->next = head1;
    } else {
        tail->next = head2;
    }

    return dummy.next;
}

int main() {
    Node* l1 = new Node{1, new Node{3, nullptr}};
    Node* l2 = new Node{2, new Node{4, nullptr}};

    Node* merged = mergeLists(l1, l2);

    cout << "Merged: ";
    while (merged != nullptr) {
        cout << merged->data << " ";
        merged = merged->next;
    }
    cout << endl;

    return 0;
}

Question: Write a function Node* insertBST(Node* root, int val) that inserts a value into a Binary Search Tree.

Code:
#include <iostream>
using namespace std;

struct Node {
    int data;
    Node* left;
    Node* right;
};

// Iterative approach to avoid stack overflow on skewed trees
Node* insertBST(Node* root, int val) {
    Node* newNode = new Node{val, nullptr, nullptr};

    if (root == nullptr) {
        return newNode;
    }

    Node* current = root;
    Node* parent = nullptr;

    while (current != nullptr) {
        parent = current;
        if (val < current->data) {
            current = current->left;
        } else {
            current = current->right;
        }
    }

    if (val < parent->data) {
        parent->left = newNode;
    } else {
        parent->right = newNode;
    }

    return root;
}

void inorder(Node* root) {
    if (root != nullptr) {
        inorder(root->left);
        cout << root->data << " ";
        inorder(root->right);
    }
}

// Helper to delete tree
void deleteTree(Node* root) {
    if (root) {
        deleteTree(root->left);
        deleteTree(root->right);
        delete root;
    }
}

int main() {
    Node* root = nullptr;
    root = insertBST(root, 50);
    insertBST(root, 30);
    insertBST(root, 20);
    insertBST(root, 40);
    insertBST(root, 70);
    insertBST(root, 60);
    insertBST(root, 80);

    cout << "Inorder: ";
    inorder(root);
    cout << endl;

    deleteTree(root);
    return 0;
}

