class Matrix {
private:
    int** mat; // Using dynamic allocation
    int rows;
    int cols;

public:
    Matrix(int r = 2, int c = 2) : rows(r), cols(c) {
        mat = new int*[rows];
        for (int i = 0; i < rows; ++i) {
            mat[i] = new int[cols];
            for (int j = 0; j < cols; ++j) {
                mat[i][j] = 0;
            }
