        if (row >= 0 && row < rows && col >= 0 && col < cols) {
            mat[row][col] = value;
        }
    }

    void setElement(int row, const std::vector<int>& row_values) {
        if (row >= 0 && row < rows) {
            for (int j = 0; j < cols; ++j) {
                if (j < row_values.size()) {
