Question: For the `StringWrapper` class (from Q20, managing dynamic C-style string), implement the copy assignment operator (`operator=`). Ensure it handles self-assignment correctly and performs a deep copy of the managed C-style string to prevent resource leaks and double-free issues.

Code:
#include <iostream>
#include <cstring> // For strlen, strcpy

class StringWrapper {
public:
    char* data;

    // Default constructor
    StringWrapper(const char* s = nullptr) : data(nullptr) {
        if (s) {
            data = new char[strlen(s) + 1];
            strcpy(data, s);
        }
    }

    // Destructor
    ~StringWrapper() {
        delete[] data;
    }

    // Copy constructor
    StringWrapper(const StringWrapper& other) : data(nullptr) {
        if (other.data) {
            data = new char[strlen(other.data) + 1];
            strcpy(data, other.data);
        }
    }

    // Helper to get C-string (for testing)
    const char* c_str() const {
        return data ? data : "";
    }

    // Copy assignment operator with a semantic error: incorrect return type (void)
    void operator=(const StringWrapper& other) { // ERROR: Should return StringWrapper&
        if (this == &other) {
            return; // No return value for void
        }

        delete[] data;

        if (other.data) {
            data = new char[strlen(other.data) + 1];
            strcpy(data, other.data);
        } else {
            data = nullptr;
        }

        // No 'return *this;' because return type is void
    }
};

