class StringWrapper {
public:
    char* data;
    size_t length;

    // Default constructor
    StringWrapper(const char* str = "") {
        if (str) {
            length = strlen(str);
            data = new char[length + 1];
            strcpy(data, str);
        } else {
            length = 0;
            data = new char[1];
            data[0] = '\0';
        }
    }

    // Copy constructor (performs deep copy - CORRECT)
    StringWrapper(const StringWrapper& other) {
        length = other.length;
        data = new char[length + 1];
        strcpy(data, other.data);
    }

    // !!! SEMANTIC ERROR: Missing destructor !!!
    // ~StringWrapper() {
    //     delete[] data;
    // }

