            day = d; // THIS IS THE SEMANTIC ERROR - assigns invalid value
            return false; // Returns false, but the object's state is corrupted
        }
    }

    // Semantic Error: Setter validates but still assigns invalid value to the member
    bool setMonth(int m) {
