Question: Create a `BankAccount` class with private members: `accountNumber` (string), `accountHolderName` (string), and `balance` (double). Implement public methods for `deposit(amount)`, `withdraw(amount)`, and `getBalance()`, ensuring `withdraw` prevents overdrafts and `deposit` accepts positive amounts only. Demonstrate encapsulation.

Code:
#include <iostream>
#include <string>

class BankAccount {
private:
    std::string accountNumber;
    std::string accountHolderName;
    double balance;

public:
    BankAccount(std::string accNum, std::string holderName, double initialBalance = 0.0)
        : accountNumber(accNum), accountHolderName(holderName), balance(initialBalance) {}

    void deposit(double amount) {
        if (amount > 0) {
            balance += amount;
            std::cout << "Deposited: " << amount << ". New balance: " << balance << std::endl;
        } else {
            std::cout << "Deposit amount must be positive." << std::endl;
        }
    }

    bool withdraw(double amount) {
        if (amount <= 0) {
            std::cout << "Withdrawal amount must be positive." << std::endl;
            return false;
        }
        if (balance - amount >= 0) { // Prevent overdrafts
            balance -= amount;
            std::cout << "Withdrew: " << amount << ". New balance: " << balance << std::endl;
            return true;
        } else {
            std::cout << "Insufficient funds. Current balance: " << balance << std::endl;
            return false;
        }
    }

    double getBalance() const {
        return balance;
    }

    std::string getAccountNumber() const {
        return accountNumber;
    }

    std::string getAccountHolderName() const {
        return accountHolderName;
    }
};

int main() {
    BankAccount myAccount("12345", "Alice Smith", 1000.0);
    std::cout << "Account: " << myAccount.getAccountNumber() << ", Holder: " << myAccount.getAccountHolderName() << std::endl;
    std::cout << "Initial Balance: " << myAccount.getBalance() << std::endl;

    myAccount.deposit(500.0);
    myAccount.withdraw(200.0);
    myAccount.withdraw(1500.0); // Should fail
    myAccount.deposit(-100.0); // Should fail

    // SEMANTIC ERROR: Attempting to directly access a private member 'balance' from outside the class
    std::cout << "Directly accessing balance (ERROR): " << myAccount.balance << std::endl;

    std::cout << "Final Balance: " << myAccount.getBalance() << std::endl;

    BankAccount otherAccount("67890", "Bob Johnson");
    std::cout << "Account: " << otherAccount.getAccountNumber() << ", Holder: " << otherAccount.getAccountHolderName() << std::endl;
    std::cout << "Initial Balance: " << otherAccount.getBalance() << std::endl;

    return 0;
}

Question: Develop a `DynamicArray` class that manages an array of integers on the heap. Include a constructor that takes size, a destructor that deallocates memory, and a method `setElement(index, value)`.

Code:
#include <iostream>

class DynamicArray {
private:
    int* arr;
    int size;

public:
    // Constructor
    DynamicArray(int s) : size(s) {
        if (s <= 0) {
            std::cout << "Warning: Array size must be positive. Setting size to 1." << std::endl;
            this->size = 1;
        }
        arr = new int[this->size];
        for (int i = 0; i < this->size; ++i) {
            arr[i] = 0; // Initialize elements to 0
        }
    }

    // Destructor
    ~DynamicArray() {
        delete[] arr;
        // Semantic Error: Attempting to deallocate the same memory twice (double-free).
        // This leads to undefined behavior and typically a program crash.
        delete[] arr; // This line causes the semantic error
        arr = nullptr; // This would be good practice, but it's too late after the double-free.
    }

    // Method to set an element
    void setElement(int index, int value) {
        if (index >= 0 && index < size) {
            arr[index] = value;
        } else {
            std::cout << "Error: Index " << index << " out of bounds for size " << size << "." << std::endl;
        }
    }

    // Helper method to print the array (for testing/demonstration)
    void printArray() const {
        for (int i = 0; i < size; ++i) {
            std::cout << arr[i] << " ";
        }
        std::cout << std::endl;
    }
};

int main() {
    DynamicArray da(5); // Creates a DynamicArray
    da.setElement(0, 10);
    da.setElement(2, 30);
    da.printArray(); // Expected output: 10 0 30 0 0 

    // When `da` goes out of scope at the end of main, its destructor `~DynamicArray()`
    // will be called, triggering the double-free error and likely crashing the program.
    return 0;
}

