        if (data_ != nullptr) {
            delete[] data_;
            data_ = nullptr;
            std::cout << "ResourceHandler destroyed. Memory at " << static_cast<void*>(data_) << " deallocated." << std::endl;
        } else {
            std::cout << "ResourceHandler destroyed (no memory to deallocate)." << std::endl;
